starterCode:
// function directionVector(dir) mein string do
// "up": [0,1], "down": [0,-1], "left": [-1,0], "right": [1,0]
// Invalid: null

solution:
function directionVector(dir) {
  switch (dir) {
    case "up": return [0, 1]
    case "down": return [0, -1]
    case "left": return [-1, 0]
    case "right": return [1, 0]
    default: return null
  }
}
